module shortest_article(\n    input clk,\n    input rst_n,\n    input start,\n    input [3:0] n,\n    input [3:0] num_proofs [0:7],\n    input [7:0] proof_len [0:7][0:3],\n    input [7:0] proof_dep [0:7][0:3],\n    output reg done,\n    output reg [15:0] result\n);\n\n// States\nlocalparam [3:0]\n    IDLE        = 4'd0,\n    INIT_DP     = 4'd1,\n    MASK_LOOP   = 4'd2,\n    CHECK_MASK  = 4'd3,\n    THEOREM_INIT= 4'd4,\n    THEOREM_LOOP= 4'd5,\n    PROOF_INIT  = 4'd6,\n    PROOF_LOOP  = 4'd7,\n    COMPARE_INIT= 4'd8,\n    COMPARE_LOOP= 4'd9,\n    FINISH      = 4'd10;\n\nreg [3:0] state;\n\n// Internal registers\nwire [7:0] mask_max = (8'd1 << n) - 8'd1;\nreg [7:0] mask_reg;\nreg [2:0] theorem_idx;\nreg [1:0] proof_idx;\nreg [15:0] dp [0:255]; // DP array\nreg [7:0] compare_idx;\nreg [15:0] min_result_reg;\n\n// Combinational logic\nwire [7:0] current_dep_mask = proof_dep[theorem_idx][proof_idx];\nwire deps_satisfied = (current_dep_mask & ~mask_reg) == 8'd0;\nwire [7:0] new_mask = mask_reg | (8'd1 << theorem_idx);\nwire [15:0] new_dp = dp[mask_reg] + {8'd0, proof_len[theorem_idx][proof_idx]};\n\n// FSM\nalways @(posedge clk or negedge rst_n) begin\n    if (!rst_n) begin\n        // Initialize all registers\n        state <= IDLE;\n        done <= 1'b0;\n        result <= 16'd0;\n        mask_reg <= 8'd0;\n        theorem_idx <= 3'd0;\n        proof_idx <= 2'd0;\n        compare_idx <= 8'd0;\n        min_result_reg <= 16'hFFFF;\n        // Initialize dp array to INF\n        for (integer k = 0; k < 256; k = k + 1) begin\n            dp[k] <= 16'hFFFF;\n        end\n    end else begin\n        case (state)\n            IDLE: begin\n                done <= 1'b0;\n                if (start) begin\n                    state <= INIT_DP;\n                end\n            end\n\n            INIT_DP: begin\n                dp[0] <= 16'd0; // Initialize dp[0]\n                mask_reg <= 8'd0;\n                state <= MASK_LOOP;\n            end\n\n            MASK_LOOP: begin\n                if (mask_reg > mask_max) begin\n                    state <= COMPARE_INIT;\n                end else begin\n                    if (dp[mask_reg] == 16'hFFFF) begin\n                        mask_reg <= mask_reg + 8'd1;\n                    end else begin\n                        theorem_idx <= 3'd0;\n                        state <= THEOREM_INIT;\n                    end\n                end\n            end\n\n            THEOREM_INIT: begin\n                state <= THEOREM_LOOP;\n            end\n\n            THEOREM_LOOP: begin\n                if (theorem_idx >= n) begin\n                    mask_reg <= mask_reg + 8'd1;\n                    state <= MASK_LOOP;\n                end else if (mask_reg[theorem_idx]) begin\n                    theorem_idx <= theorem_idx + 3'd1;\n                end else begin\n                    proof_idx <= 2'd0;\n                    state <= PROOF_INIT;\n                end\n            end\n\n            PROOF_INIT: begin\n                state <= PROOF_LOOP;\n            end\n\n            PROOF_LOOP: begin\n                if (proof_idx >= num_proofs[theorem_idx]) begin\n                    theorem_idx <= theorem_idx + 3'd1;\n                    state <= THEOREM_LOOP;\n                end else begin\n                    if (deps_satisfied && (new_dp < dp[new_mask])) begin\n                        dp[new_mask] <= new_dp;\n                    end\n                    proof_idx <= proof_idx + 2'd1;\n                end\n            end\n\n            COMPARE_INIT: begin\n                compare_idx <= 8'd0;\n                min_result_reg <= 16'hFFFF;\n                state <= COMPARE_LOOP;\n            end\n\n            COMPARE_LOOP: begin\n                if (compare_idx <= mask_max) begin\n                    if (compare_idx[0] && (dp[compare_idx] < min_result_reg)) begin\n                        min_result_reg <= dp[compare_idx];\n                    end\n                    compare_idx <= compare_idx + 8'd1;\n                end else begin\n                    result <= min_result_reg;\n                    state <= FINISH;\n                end\n            end\n\n            FINISH: begin\n                done <= 1'b1;\n                state <= IDLE;\n            end\n\n            default: state <= IDLE;\n        endcase\n    end\nend\n\nendmodule